from math import isqrt

def ceil_div(a, b):
    return -((-a) // b)

def r_formula(N):
    # exact integer value of ceil((1+sqrt(1+8N))/2)
    d = 1 + 8 * N
    s = isqrt(d)
    if s * s == d:
        return ceil_div(1 + s, 2)
    else:
        return ceil_div(1 + s + 1, 2)

def r_min(N):
    k = 1
    while k * (k - 1) // 2 < N:
        k += 1
    return k

def verify(witness):
    n_min = witness["range"]["N_min"]
    n_max = witness["range"]["N_max"]
    if n_min != 1 or n_max != 1000000:
        raise ValueError("bad range")
    if witness["claim_formula"] != "r(N) = ceil((1+sqrt(1+8N))/2) = min{k : C(k,2) >= N}":
        raise ValueError("claim formula mismatch")
    for N in range(n_min, n_max + 1):
        rf = r_formula(N)
        if rf != r_min(N):
            raise ValueError("formula != min at N=%d" % N)
        if not ((rf - 1) * (rf - 2) // 2 < N):
            raise ValueError("lower direction fails at N=%d" % N)
        if not (rf * (rf - 1) // 2 >= N):
            raise ValueError("upper direction fails at N=%d" % N)
